const messages = $input.all();

const combinedMessage = messages
  .map(item => item.json.content)
  .join('\n');

const chatId = messages[0]?.json.key;
const messageCount = messages.length;

return [
  {
    json: {
      chat_id: chatId,
      message_count: messageCount,
      content: combinedMessage
    }
  }
];
